// Closing: MAIN site only, and only after a completed authority lookup in this
// session, within the last hour, that returned a GRANTED decision by a HUMAN
// approver for this same work order and site. Only ::response events are
// matched, so denied or failed lookups (recorded as ::error) never count.
@id("close-main-with-human-approval")
permit (principal, action == Drupe::Action::"close_workorder", resource)
when { context.input.site_id == "MAIN" }
when temporal {
  formerly within 1h Drupe::Action::"authority_get_approval"::response{
    eventResource: resource,
    input.site_id: context.input.site_id,
    input.wonum: context.input.wonum,
    output.decision: "GRANTED",
    output.approver_kind: "HUMAN"
  }
};

// The prerequisite lookup must itself be permitted, or it is never recorded as a response.
@id("allow-authority-approval-lookup")
permit (principal, action == Drupe::Action::"authority_get_approval", resource);

// Read-only lookups the agent may use freely.
@id("allow-read-only-lookups")
permit (principal, action in [
  Drupe::Action::"list_workorders",
  Drupe::Action::"get_approval_record",
  Drupe::Action::"get_workorder_tasks",
  Drupe::Action::"get_workorder_costs",
  Drupe::Action::"get_workorder_actuals_vs_planned",
  Drupe::Action::"get_workorder_kpis",
  Drupe::Action::"get_schedule_calendar",
  Drupe::Action::"get_my_assigned_workorders",
  Drupe::Action::"get_failure_codes"
], resource);

// No permit exists for approve_workorder, generate_work_order, update_workorder,
// assign_technician or cancel_workorder, so they are denied by default.
// The agent therefore cannot approve work orders, directly or indirectly.
